import {filterProducts,isSaved,enhanceStore,enhanceOrder,enhanceAdmin,showWishlist,showHelp,showTrack} from '/enhancements.js?v=rail-only-2';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cash=n=>new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN',maximumFractionDigits:2}).format(n/100);
let shop,adminData,csrf='',adminTab='Products',cart=[];try{cart=JSON.parse(localStorage.getItem('bagz-cart')||'[]');if(!Array.isArray(cart))cart=[];}catch{}
const count=()=>cart.reduce((a,i)=>a+i.quantity,0);
function saveCart(){localStorage.setItem('bagz-cart',JSON.stringify(cart));const c=$('#cart-count');if(c)c.textContent=count();}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
async function api(path,data){const r=await fetch(path,{method:data===undefined?'GET':'POST',headers:{'Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{})},...(data===undefined?{}:{body:JSON.stringify(data)}),signal:AbortSignal.timeout(22000)});const type=r.headers.get('content-type')||'';let result;try{result=type.includes('application/json')?await r.json():null;}catch{}if(!result||typeof result!=='object'){const e=new Error(type.includes('text/html')?'This store API route is not deployed yet. Redeploy the latest GitHub main branch.':'The store returned an invalid response. Please try again.');e.status=r.status;throw e;}if(!r.ok){const e=new Error(result.error||'Request failed');e.result=result;e.status=r.status;throw e;}return result;}
let logoClicks=0,logoTimer;
document.addEventListener('click',event=>{const logo=event.target.closest('.header .brand');if(!logo||event.ctrlKey||event.metaKey||event.shiftKey||event.button!==0)return;event.preventDefault();clearTimeout(logoTimer);logoClicks++;if(logoClicks>=4){logoClicks=0;location.assign('/admin');return;}logoTimer=setTimeout(()=>{logoClicks=0;if(location.pathname!=='/')location.assign('/');},700);});
function shell(content){document.body.classList.toggle('home',location.pathname==='/');const s=shop?.settings||{brand:'Orẽva'};$('#app').innerHTML=`<div class="topbar">CAMPUS DAYS. EVERYDAY STYLE. &nbsp; · &nbsp; FREE ACU PICKUP</div><div class="header-band"><div class="wrap"><header class="header"><a class="brand ${s.logo?'brand-logo':''}" href="/" aria-label="${esc(s.brand)} home">${s.logo?`<img src="${esc(s.logo)}" alt="${esc(s.brand)}">`:esc(s.brand)}</a><nav class="nav" aria-label="Main navigation"><a href="/shop">Shop</a><a class="desktop" href="/request">Request an item</a><a class="cart-link" href="/cart">Bag <span id="cart-count">${count()}</span></a></nav></header></div></div>${shop?`<div class="mode">${shop.mode==='disabled'?'Our collection is being prepared · Online checkout is not open yet.':shop.mode==='live'?'Secure checkout powered by Paystack.':'Paystack TEST mode · No live purchases.'}</div>`:''}<main id="main" class="wrap" tabindex="-1">${content}</main><div class="wrap"><footer class="footer"><div><a class="brand" href="/">${esc(s.brand)}</a><p>${esc(s.tagline||'Timeless elegance.')}</p></div><div><a href="/request">Request an item</a> &nbsp; / &nbsp; <a href="/help">Customer care</a><p>Free ACU pickup · Local delivery where available</p><p><a href="/help">Pickup, delivery & customer care ↗</a></p></div></footer></div>`;}
function image(p,cls=''){return p.photo?`<img class="${cls}" src="${esc(p.photo)}" alt="${esc(p.name)}${p.sample?' — illustration, not a real product photo':''}" loading="lazy">`:`<div class="empty ${cls}">Photo coming soon</div>`;}
function cards(products){return products.length?products.map(p=>`<article class="card-shell"><button class="save-piece" data-save="${esc(p.id)}" aria-label="Save ${esc(p.name)}" aria-pressed="${isSaved(p.id)}">${isSaved(p.id)?'♥':'♡'}</button><a class="product-card" href="/product/${encodeURIComponent(p.id)}"><div class="image">${image(p)}<span class="badge">${p.sample?'DEVELOPMENT SAMPLE':p.variants.some(v=>v.available>0)?'IN STOCK':'SOLD OUT'}</span></div><p class="eyebrow">${esc(p.category)}</p><h3>${esc(p.name)}</h3><div class="meta"><span>${esc([...new Set(p.variants.map(v=>v.colour))].join(' / '))}</span><span class="price">${cash(Math.min(...p.variants.map(v=>v.price)))}</span></div></a></article>`).join(''):`<div class="empty"><h2>No pieces here yet.</h2><p>Try another search, or request something you love.</p><a class="button secondary" href="/request">Request an item ↗</a></div>`;}
function catalogue(home=false){shell(`${home?`<section class="couture-hero campaign-hero"><img class="campaign-image" src="/campaign-bag.png" alt="Black Bagz & Co. handbag campaign photograph" fetchpriority="high"><div class="couture-copy"><p class="eyebrow">BAGS, SHOES & EVERYDAY STYLE</p><h1>TIMELESS<br>ELEGANCE.</h1><p>Timeless style for every chapter.<br>Find your next everyday favourite.</p><a class="button ivory" href="/shop">SHOP NOW <span aria-hidden="true">→</span></a></div><div class="hero-bottom"><span>STYLE INSPIRATION · SEE SHOP FOR AVAILABLE STOCK</span><span>${shop.mode==='disabled'?'ONLINE CHECKOUT COMING SOON':'TEST PAYMENTS ONLY'}</span></div></section><section class="brand-intro"><div><span class="fine-rule"></span><h2>Small details.<br>A lasting impression.</h2></div><div><p>From a full day on campus to a moment that is all yours. Discover bags and shoes for the way you move.</p><a class="text-link" href="/shop">Meet your next favourite ↗</a></div></section><div class="store-promises"><div><span>THE COLLECTION</span><strong>Bags & shoes</strong></div><div><span>AT ACU</span><strong>Free pickup</strong></div><div><span>BEFORE YOU PAY</span><strong>Clear totals</strong></div><div><span>READY FOR YOU</span><strong>Available stock</strong></div></div>`:''}<section class="section collection-section" id="collection"><div class="section-head"><div><p class="eyebrow">FIND YOUR EVERYDAY FAVOURITE</p><h${home?'2':'1'} class="${home?'':'page-title'}">${home?'The everyday collection':'Shop the collection.'}</h${home?'2':'1'}></div><span class="muted" id="results-count">${shop.products.length} pieces</span></div><div class="toolbar"><div class="filters" aria-label="Product categories">${['All','Bags','Shoes'].map((c,i)=>`<button class="${!i?'active':''}" data-category="${c}" aria-pressed="${!i}">${c==='All'?'All pieces':c}</button>`).join('')}</div><label class="search"><span class="eyebrow">Search</span><input id="search" type="search" placeholder="Find your next favourite…" aria-label="Search products"></label></div><div class="catalogue-options"><label>Sort by<select id="catalogue-sort"><option value="featured">Featured</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="name">Name A–Z</option></select></label><label>Colour<select id="catalogue-colour"><option value="">All colours</option>${[...new Set(shop.products.flatMap(p=>p.variants.map(v=>v.colour)))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label>Size<select id="catalogue-size"><option value="">All sizes</option>${[...new Set(shop.products.flatMap(p=>p.variants.map(v=>v.size)))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label>Maximum price (₦)<input id="catalogue-max" type="number" min="0" step="100" placeholder="Any price"></label><label class="check"><input id="catalogue-stock" type="checkbox">In stock only</label></div><div class="grid" id="product-grid">${cards(shop.products)}</div></section>${home?`<section class="inspiration-gallery" aria-labelledby="inspiration-title"><div class="section-head"><div><p class="eyebrow">THE ORẼVA EDIT</p><h2 id="inspiration-title">A little inspiration.</h2><p>Display inspiration only. Availability and prices appear in the shop when confirmed.</p></div></div><div class="inspiration-grid"><figure><img src="/display-loafers.jpg" alt="Black bow loafers — display inspiration" loading="lazy"><figcaption>STYLE INSPIRATION</figcaption></figure><figure><img src="/display-flats.jpg" alt="Black pointed flats — display inspiration" loading="lazy"><figcaption>STYLE INSPIRATION</figcaption></figure><figure><img src="/display-bag-pink.jpg" alt="Pink shoulder bag — display inspiration" loading="lazy"><figcaption>STYLE INSPIRATION</figcaption></figure><figure><img src="/display-bag-rose.jpg" alt="Rose shoulder bag — display inspiration" loading="lazy"><figcaption>STYLE INSPIRATION</figcaption></figure><figure><img src="/display-bag-burgundy.jpg" alt="Burgundy quilted handbag — display inspiration" loading="lazy"><figcaption>STYLE INSPIRATION</figcaption></figure></div></section><section class="editorial-strip">${shop.settings.bagDisplay?`<div class="editorial-image"><img src="${esc(shop.settings.bagDisplay)}" alt="Bag style inspiration; see catalogue for available stock" loading="lazy"><span>STYLE INSPIRATION</span></div>`:""}<div class="editorial-story"><p class="eyebrow">THE Orẽva WAY</p><h2>Carry more <br>than the <br><em>ordinary.</em></h2><a class="button ivory" href="/shop">Discover the edit ↗</a></div>${shop.settings.shoeDisplay?`<div class="editorial-image shoes"><img src="${esc(shop.settings.shoeDisplay)}" alt="Slip-on style inspiration; see catalogue for available stock" loading="lazy"><span>STYLE INSPIRATION</span></div>`:""}</section><div class="editorial-marquee" aria-label="Shop benefits"><span>Free ACU pickup</span><b>/</b><span>Your everyday style</span><b>/</b><span>Timeless elegance</span></div>`:''}<section class="request-banner"><div><p class="eyebrow">SOMETHING ELSE IN MIND?</p><h2>Don't see what you like?</h2><p>Tell us about your dream bag or pair. Start a conversation on WhatsApp and send your reference photos there.</p></div><a class="button secondary" href="/request">Request an item ↗</a></section>`);
let category='All';const filter=()=>{const term=$('#search').value.toLowerCase();const products=filterProducts(shop.products,{term,category,colour:$('#catalogue-colour').value,size:$('#catalogue-size').value,available:$('#catalogue-stock').checked,sort:$('#catalogue-sort').value,maxPrice:$('#catalogue-max').value});$('#product-grid').innerHTML=cards(products);$('#results-count').textContent=products.length+' pieces';};$('#search').oninput=filter;['#catalogue-sort','#catalogue-colour','#catalogue-size','#catalogue-stock','#catalogue-max'].forEach(id=>$(id).oninput=filter);$$('[data-category]').forEach(b=>b.onclick=()=>{category=b.dataset.category;$$('[data-category]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b);});filter();});}
function product(id){const p=shop.products.find(p=>p.id===id);if(!p)throw Error('This product is not available.');shell(`<div class="page"><p class="breadcrumb"><a href="/shop">Shop</a> / ${esc(p.category)}</p><div class="detail"><div>${image(p,'detail-photo')}</div><div><p class="eyebrow">${esc(p.category)} / THE EVERYDAY EDIT</p><h1>${esc(p.name)}</h1>${p.sample?'<div class="notice">Development sample · Illustration and price are for testing, not a real product offer.</div>':''}<div id="variant-price" class="price"></div><form id="add-form" class="form"><label>${p.category==='Bags'?'Colour':'Colour / size'}<select name="variant" id="variant">${p.variants.map(v=>`<option value="${esc(v.id)}">${esc(v.colour)}${p.category==='Bags'?'':' / '+esc(v.size)}${v.available?'':' — Sold out'}</option>`).join('')}</select></label><p id="stock" class="stock" aria-live="polite"></p><label>Quantity<input name="quantity" type="number" min="1" value="1" required></label><button id="add-button" class="full">Add to bag &nbsp; +</button></form><div class="description">${esc(p.description)}</div><p class="muted">Free ACU pickup · ${esc(shop.settings.pickupTime)}</p><a class="link" href="/request">Looking for a different colour or size? ↗</a></div></div></div>`);const update=()=>{const v=p.variants.find(v=>v.id===$('#variant').value);$('#variant-price').textContent=cash(v.price);$('#stock').textContent=v.available?`${v.available} available in this option`:'This option is currently sold out';$('#add-button').disabled=!v.available;$('[name=quantity]').max=v.available;};$('#variant').onchange=update;update();$('#add-form').onsubmit=e=>{e.preventDefault();const v=p.variants.find(v=>v.id===$('#variant').value),q=Number($('[name=quantity]').value),old=cart.find(i=>i.variant===v.id);if(!Number.isInteger(q)||q<1||q+(old?.quantity||0)>v.available){toast('That quantity is not available.');return;}if(old)old.quantity+=q;else cart.push({variant:v.id,quantity:q});saveCart();toast('Added to your bag');};}
function cartLines(){return cart.map(i=>{const p=shop.products.find(p=>p.variants.some(v=>v.id===i.variant));return p?{...i,p,v:p.variants.find(v=>v.id===i.variant)}:{...i,missing:true};});}
function cartPage(){const lines=cartLines();shell(`<div class="page"><p class="eyebrow">YOUR EVERYDAY FINDS</p><h1 class="page-title">Your bag.</h1>${!lines.length?'<div class="empty"><h2>A little room for something lovely.</h2><a class="button" href="/shop">Explore the collection</a></div>':`<div class="two-col"><div>${lines.map(l=>l.missing?`<div class="cart-row"><p>Item no longer available</p><button data-remove="${esc(l.variant)}">Remove</button></div>`:`<div class="cart-row">${image(l.p)}<div><h3><a href="/product/${esc(l.p.id)}">${esc(l.p.name)}</a></h3><p class="muted">${esc(l.v.colour)}${l.p.category==='Bags'?'':' / '+esc(l.v.size)}</p><div class="qty"><button data-qty="${esc(l.variant)}" data-delta="-1" aria-label="Decrease quantity">−</button><span>${l.quantity}</span><button data-qty="${esc(l.variant)}" data-delta="1" aria-label="Increase quantity">+</button><button class="link" data-remove="${esc(l.variant)}" aria-label="Remove ${esc(l.p.name)}">Remove</button></div>${l.quantity>l.v.available?'<p class="error">Quantity no longer available. Please reduce it.</p>':''}</div><div class="price">${cash(l.v.price*l.quantity)}</div></div>`).join('')}</div><aside class="summary"><h2>Bag summary</h2><div class="summary-row"><span>Items</span><span>${cash(lines.reduce((a,l)=>a+(l.v?.price||0)*l.quantity,0))}</span></div><p class="muted">Pickup is free. Any delivery fee and your timeframe are shown before payment.</p><a class="button full" href="/checkout">Continue to checkout →</a><p class="muted spaced">Your stock is reserved when you proceed to payment.</p></aside></div>`}</div>`);$$('[data-remove]').forEach(b=>b.onclick=()=>{cart=cart.filter(i=>i.variant!==b.dataset.remove);saveCart();cartPage();});$$('[data-qty]').forEach(b=>b.onclick=()=>{const l=lines.find(i=>i.variant===b.dataset.qty),q=l.quantity+Number(b.dataset.delta);if(q<1||q>l.v.available){toast('Choose an available quantity.');return;}cart.find(i=>i.variant===l.variant).quantity=q;saveCart();cartPage();});}
function deliveryFields(){return `<label>Pickup or delivery<select name="method" id="method"><option value="pickup">Free ACU pickup — ₦0</option>${shop.settings.deliveryAreas.map(a=>`<option value="${esc(a.id)}">${esc(a.name)} — ${cash(a.fee)}</option>`).join('')}</select></label><label id="address-label" hidden>Delivery address<textarea name="address" autocomplete="street-address" maxlength="500"></textarea></label>`;}
function customerFields(){return `<label>Full name<input name="name" autocomplete="name" maxlength="120" required></label><div class="form-row"><label>Email<input name="email" type="email" autocomplete="email" maxlength="254" required></label><label>Nigerian phone number<input name="phone" type="tel" autocomplete="tel" placeholder="080… or +234…" maxlength="30" required></label></div>`;}
function wireDelivery(callback=()=>{}){const update=()=>{const area=shop.settings.deliveryAreas.find(a=>a.id===$('#method').value);$('#address-label').hidden=!area;$('[name=address]').required=!!area;callback(area);};$('#method').onchange=update;update();}
function bindForm(id,fn){$(id).onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button[type=submit]')||f.querySelector('button:not([type])');if(b)b.disabled=true;try{await fn(Object.fromEntries(new FormData(f)),f);}catch(err){const target=f.querySelector('.form-error');if(target){target.textContent=err.message;target.focus();}else toast(err.message);}finally{if(b)b.disabled=false;}};}
function checkout(){if(shop.mode==='disabled'){shell('<div class="page narrow"><h1 class="page-title">Checkout is not open yet.</h1><p class="notice">Online checkout is not configured yet. Your bag is saved; no payment will be attempted.</p><a class="button secondary" href="/cart">Back to your bag</a></div>');return;}const lines=cartLines();if(!lines.length){cartPage();return;}const subtotal=lines.reduce((a,l)=>a+(l.v?.price||0)*l.quantity,0);shell(`<div class="page"><p class="breadcrumb"><a href="/cart">Your bag</a> / Checkout</p><h1 class="page-title">Make it yours.</h1><div class="notice">${shop.mode==='live'?'Secure Paystack checkout.':'Paystack TEST checkout · No live charges.'} Stock is reserved for 30 minutes.</div><div class="two-col"><form id="checkout" class="form"><h3>1. Your details</h3>${customerFields()}<h3 class="spaced">2. How should it reach you?</h3>${deliveryFields()}<div class="notice" id="fulfil-info"></div><p class="form-error error" role="alert" tabindex="-1"></p><button type="submit">${shop.mode==='live'?'Continue to secure checkout →':'Continue to secure test checkout →'}</button><small>Guest checkout. Keep your private order link safe.</small></form><aside class="summary"><h2>Your order</h2>${lines.map(l=>`<div class="summary-row"><span>${l.quantity} × ${esc(l.p?.name||'Unavailable item')}</span><span>${cash((l.v?.price||0)*l.quantity)}</span></div>`).join('')}<div class="summary-row"><span>Delivery</span><span id="delivery-total"></span></div><div class="summary-row total"><span>Total</span><span id="checkout-total"></span></div><p class="muted">All amounts in Nigerian naira. Card details are collected only on Paystack’s hosted page.</p><p id="checkout-eta"></p></aside></div></div>`);wireDelivery(a=>{$('#delivery-total').textContent=cash(a?.fee||0);$('#checkout-total').textContent=cash(subtotal+(a?.fee||0));$('#checkout-eta').textContent='Estimated: '+(a?.timeframe||shop.settings.pickupTime);$('#fulfil-info').textContent=a?'Delivery to your address in '+a.name+'. '+a.timeframe:shop.settings.pickupInstructions+' '+shop.settings.pickupTime;});const key=crypto.randomUUID();bindForm('#checkout',async d=>{const result=await api('/api/checkout',{...d,items:cart.map(({variant,quantity})=>({variant,quantity})),idempotency:key});sessionStorage.setItem('bagz-last-order',result.statusUrl);location.assign(result.checkoutUrl);});}

function requestPage(){shell(`<div class="page narrow"><p class="eyebrow">LET'S FIND YOUR KIND OF LOVELY</p><h1 class="page-title">Your wish list.<br>Our next conversation.</h1><p class="muted">Tell us what you’re looking for. We’ll prepare a WhatsApp message; you choose Send there.</p><form id="request-form" class="form"><label>What are you looking for?<textarea name="description" placeholder="Describe the bag or shoes you would like…" maxlength="1500" required></textarea></label><label>Item type<select name="category" id="request-category"><option value="Bags">Bag</option><option value="Shoes">Shoes</option></select></label><label>Preferred colour<input name="colour" maxlength="100" required></label><label id="request-size-label" hidden>Preferred shoe size<input name="size" id="request-size" maxlength="100"></label><label>Budget in naira (optional)<input name="budget" type="number" min="0" step="100" max="10000000"></label><div class="notice">WhatsApp will open with a prepared message. Review it, tap <strong>Send</strong>, and attach any reference photos there. This is a request, not an order or payment.</div>${!shop.settings.whatsapp?'<p class="notice">WhatsApp requests will be available once the owner adds the business number.</p>':''}<button type="submit" ${!shop.settings.whatsapp?'disabled':''}>Prepare WhatsApp message ↗</button><div id="whatsapp-link"></div></form></div>`);const category=$('#request-category'),size=$('#request-size');const updateSize=()=>{$('#request-size-label').hidden=category.value!=='Shoes';size.required=category.value==='Shoes';if(category.value==='Bags')size.value='';};category.onchange=updateSize;updateSize();bindForm('#request-form',async data=>{const isShoe=data.category==='Shoes',message=`Hello ${shop.settings.brand}! I’d like to request an item.\n\nItem: ${data.description}\nType: ${isShoe?'Shoes':'Bag'}\nColour: ${data.colour}${isShoe?'\nShoe size: '+data.size:''}\nBudget: ${data.budget?cash(Math.round(Number(data.budget)*100)):'Not specified'}\n\nI’ll attach my reference photos here.`;const url='https://wa.me/'+shop.settings.whatsapp+'?text='+encodeURIComponent(message);$('#whatsapp-link').innerHTML=`<a class="button full" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Open WhatsApp, then tap Send ↗</a>`;});}
function receipt(o){return `<section class="panel receipt"><p class="eyebrow">${o.receipt?'PAYMENT RECEIPT':'ORDER SUMMARY'}</p><h2>${esc(o.receipt||o.number)}</h2><p>Payment: <strong>${esc(o.payment)}</strong>${o.paid_at?' · '+new Date(o.paid_at).toLocaleString('en-NG',{timeZone:'Africa/Lagos',timeZoneName:'short'}):''}</p><table><thead><tr><th>Item</th><th>Amount</th></tr></thead><tbody>${o.items.map(i=>`<tr><td>${i.quantity} × ${esc(i.name)}<br><span class="muted">${esc(i.colour)} / ${esc(i.size)}</span></td><td>${cash(i.quantity*i.price)}</td></tr>`).join('')}<tr><td>Delivery / pickup</td><td>${cash(o.delivery)}</td></tr><tr><th>Total (NGN)</th><th>${cash(o.total)}</th></tr>${o.refunded?`<tr><td>Confirmed refunds</td><td>${cash(o.refunded)}</td></tr>`:''}</tbody></table>${o.receipt?'<button class="secondary spaced" id="print-receipt">Print / save receipt</button>':''}</section>`;}
async function orderPage(token,development=false){let o=await api('/api/order/'+token);if(!development&&shop.mode!=='development'&&o.payment!=='paid'){try{o=await api('/api/order/'+token+'/verify',{});}catch(e){toast(e.message);}}if(o.payment==='paid'&&sessionStorage.getItem('bagz-last-order')==='/order/'+token){cart=[];saveCart();sessionStorage.removeItem('bagz-last-order');}const payable=o.payment==='pending'&&!o.cancelled&&o.expires>Date.now();const stages=['Paid','Preparing',o.instructions.startsWith('Delivery to')?'Out for delivery':'Ready for pickup','Completed'];shell(`<div class="page narrow"><p class="eyebrow">${development?'DEVELOPMENT PAYMENT ADAPTER':'YOUR ORDER'}</p><h1 class="status-title">${esc(o.number)}</h1>${development?'<div class="notice">Development adapter only. These controls exercise the order logic without collecting money. This screen is unavailable in production.</div>':''}<p>Payment: <span class="pill ${esc(o.payment)}">${esc(o.payment)}</span> &nbsp; Fulfilment: <strong>${esc(o.fulfilment)}</strong></p>${o.exception?`<div class="notice">${esc(o.exception)}</div>`:''}${o.payment==='paid'&&!o.cancelled&&!o.exception?`<div class="status-steps">${stages.map((s,i)=>`<div class="step ${i<=stages.indexOf(o.fulfilment)?'done':''}">${esc(s)}</div>`).join('')}</div>`:''}<div class="notice success"><strong>Estimated fulfilment:</strong> ${esc(o.timeframe)}<br>${esc(o.instructions)}</div>${payable?`<p>Reservation expires ${new Date(o.expires).toLocaleString('en-NG',{timeZone:'Africa/Lagos',timeZoneName:'short'})}. Total before payment: <strong>${cash(o.total)}</strong>.</p>${development?'<div class="form"><button data-simulate="success">Simulate successful test payment</button><button class="secondary" data-simulate="failed">Simulate failed payment</button><button class="secondary" data-simulate="abandoned">Simulate abandoned payment</button></div>':'<button id="pay-order" class="full">Continue to payment →</button>'}`:o.payment!=='paid'?'<div class="notice">This checkout is no longer payable. If you already paid, use Check payment status. Otherwise, return to the shop to create a new checkout.</div>':''}<button id="verify-order" class="secondary spaced">Check payment status</button><p class="muted spaced">Bookmark this private link to follow your order. Anyone with the link can view this order, so share it carefully.</p>${receipt(o)}</div>`);if($('#print-receipt'))$('#print-receipt').onclick=()=>window.print();if($('#pay-order'))$('#pay-order').onclick=async()=>{try{const r=await api('/api/order/'+token+'/pay',{});location.href=r.checkout;}catch(e){toast(e.message);}};$('#verify-order').onclick=async()=>{try{await api('/api/order/'+token+'/verify',{});await orderPage(token);toast('Order status refreshed');}catch(e){toast(e.message);}};$$('[data-simulate]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('/api/order/'+token+'/simulate',{status:b.dataset.simulate});location.href='/order/'+token;}catch(e){toast(e.message);b.disabled=false;}});if(!o.timeline)o=await api('/api/order/'+token);enhanceOrder(context(),o);}

function login(){shell(`<div class="page narrow"><p class="eyebrow">OWNER ACCESS</p><h1 class="page-title">Your shop, at a glance.</h1><p class="muted">Sign in with an owner account designated for this store.</p><form id="login" class="form panel"><label>Email<input type="email" name="email" autocomplete="username" required></label><label>Password<input type="password" name="password" autocomplete="current-password" required maxlength="300"></label><p class="form-error error" role="alert" tabindex="-1"></p><button type="submit">Sign in securely →</button></form><p class="muted spaced">Owner accounts are managed in Supabase and must be explicitly designated for this store.</p></div>`);bindForm('#login',async d=>{const r=await api('/api/login',d);csrf=r.csrf;await admin();});}
async function ownerSetup(){const setup=await api('/api/setup');shell(`<div class="page narrow"><p class="eyebrow">PRIVATE OWNER SETUP</p><h1 class="page-title">Make it yours.</h1>${setup.enabled?`<p>Create your private owner login. Use a unique password with at least 14 characters.</p><form id="owner-setup" class="form panel">${setup.codeRequired?'<label>Private setup code<input name="code" type="password" autocomplete="off" required><small>Use the OWNER_SETUP_CODE configured on your backend host.</small></label>':''}<label>Your email<input name="email" type="email" autocomplete="username" required></label><label>Create password<input name="password" type="password" autocomplete="new-password" minlength="14" maxlength="300" required></label><label>Repeat password<input name="confirm" type="password" autocomplete="new-password" required></label><p class="form-error error" role="alert" tabindex="-1"></p><button>Create owner account</button></form>`:'<p>Owner setup is closed. Sign in with your existing account, or follow the backend setup instructions if no account has been created.</p>'}<p><a href="/admin">Owner sign-in</a></p></div>`);if(setup.enabled)bindForm('#owner-setup',async d=>{if(d.password!==d.confirm)throw Error('Passwords do not match');await api('/api/setup',d);location.assign('/admin');});}
async function admin(){try{const me=await api('/api/admin/me');csrf=me.csrf;adminData=await api('/api/admin/overview');adminData.pushKey=me.pushKey;renderAdmin();}catch(e){if(e.status===401)login();else throw e;}}
const errorField='<p class="form-error error" role="alert" tabindex="-1"></p>';
function renderAdmin(){const d=adminData,r=d.report;shell(`<div class="page"><div class="admin-head"><div><p class="eyebrow">Orẽva / OWNER DESK</p><h1>Your shop, in order.</h1></div><button class="secondary small" id="logout">Sign out</button></div><nav class="admin-tabs" aria-label="Dashboard sections">${['Products','Images','Settings'].map(t=>`<button data-tab="${t}" class="${t===adminTab?'active':''}">${t}</button>`).join('')}</nav><div class="stats"><div class="stat"><span>Net revenue</span><strong>${d.capabilities?.reports===false?'Not connected':cash(r.revenue)}</strong></div><div class="stat"><span>Estimated profit</span><strong>${d.capabilities?.reports===false?'Not connected':cash(r.estimatedProfit)}</strong></div><div class="stat"><span>To fulfil</span><strong>${d.capabilities?.orders===false?'Not connected':r.outstanding}</strong></div><div class="stat"><span>Low-stock options</span><strong>${d.products.flatMap(p=>p.variants).filter(v=>v.available<=d.settings.lowStock).length}</strong></div></div><div id="admin-content"></div></div>`);$('#logout').onclick=async()=>{await api('/api/admin/logout',{});csrf='';login();};$$('[data-tab]').forEach(b=>b.onclick=()=>{adminTab=b.dataset.tab;renderAdmin();});({Products:adminProducts,Images:adminImages,Settings:adminSettings}[adminTab]||(()=>{}))();}
async function mutate(path,data){await api(path,data);await admin();toast('Saved');}
function adminOrders(){const orders=adminData.orders;$('#admin-content').innerHTML=`<div class="section-head"><h2>Orders</h2><button class="secondary small" id="refresh">Refresh</button></div><label class="field">Find an order<input id="order-search" type="search" placeholder="Order number, customer or payment reference"></label><div id="order-list" class="spaced"></div>`;const render=()=>{const q=$('#order-search').value.toLowerCase();$('#order-list').innerHTML=orders.filter(o=>`${o.number} ${o.name} ${o.email} ${o.reference}`.toLowerCase().includes(q)).map(o=>{const stages=['Paid','Preparing',o.method==='pickup'?'Ready for pickup':'Out for delivery','Completed'],next=stages[stages.indexOf(o.fulfilment)+1];return `<article class="order-card"><div class="order-head"><div><h3>${esc(o.number)} ${o.custom?'<span class="pill">Custom</span>':''}</h3><p>${esc(o.name)} · ${cash(o.total)} · ${new Date(o.created).toLocaleString('en-NG',{timeZone:'Africa/Lagos',timeZoneName:'short'})}</p></div><div><span class="pill ${esc(o.payment)}">Payment: ${esc(o.payment)}</span> <span class="pill">${esc(o.fulfilment)}</span></div></div>${o.exception?`<div class="notice">${esc(o.exception)}</div>`:''}<details><summary>Customer, items, payment & receipt</summary><p>${esc(o.email)} · ${esc(o.phone)}</p><p>${esc(o.address||o.instructions)} · ${esc(o.timeframe)}</p><p>${o.items.map(i=>`${i.quantity} × ${esc(i.name)} / ${esc(i.colour)} / ${esc(i.size)}`).join('<br>')}</p><p>Reference: ${esc(o.reference)}<br>Last payment check: ${o.payment_checked?new Date(o.payment_checked).toLocaleString('en-NG',{timeZone:'Africa/Lagos',timeZoneName:'short'}):'Not checked'}${o.payment_check_error?'<br>'+esc(o.payment_check_error):''}<br>Receipt: ${esc(o.receipt||'Awaiting verified payment')}<br>Confirmed refund: ${cash(o.refunded)}</p><a class="link" href="/order/${o.token}" target="_blank" rel="noopener">Open private order / receipt ↗</a></details><div class="actions">${o.payment==='paid'&&o.allocated&&!o.cancelled&&!o.refunded&&next?`<button class="small" data-order="${o.id}" data-action="fulfil" data-state="${next}">Mark ${next}</button>`:''}${o.payment!=='paid'?`<button class="secondary small" data-order="${o.id}" data-action="verify">Reconcile payment</button>`:''}${!o.cancelled&&o.fulfilment!=='Completed'?`<button class="danger small" data-order="${o.id}" data-action="cancel">Cancel order</button>`:''}${o.payment==='paid'?`<button class="secondary small" data-order="${o.id}" data-action="refund">Verify a Paystack refund</button>`:''}${o.cancelled&&o.allocated&&!o.restocked?`<button class="secondary small" data-order="${o.id}" data-action="restock">Confirm return & restock</button>`:''}</div></article>`;}).join('')||'<div class="empty">No matching orders yet.</div>';$$('[data-order]').forEach(b=>b.onclick=async()=>{try{const data={id:b.dataset.order,action:b.dataset.action,state:b.dataset.state};if(data.action==='cancel'&&!confirm('Cancel this order? This does not refund money or restock items.'))return;if(data.action==='restock'){if(!confirm('Confirm that these items are physically back in available stock.'))return;data.confirmPhysicalReturn=true;}if(data.action==='refund'){const id=prompt('Enter the refund ID from Paystack. Only a provider-confirmed processed refund will be recorded.');if(!id)return;data.refundId=id;}await mutate('/api/admin/order',data);}catch(e){toast(e.message);}});};$('#order-search').oninput=render;$('#refresh').onclick=admin;render();}
function adminProducts(){$('#admin-content').innerHTML=`<div class="section-head"><h2>Your pieces</h2><button id="new-product">Add product +</button></div><p class="muted">Quantities are physical stock before active reservations. Available quantities exclude reservations.</p>${adminData.products.map(p=>`<div class="admin-product">${image(p)}<div><h3>${esc(p.name)}</h3><p class="muted">${p.visible?'Visible':'Hidden'}${p.sample?' · Development sample':''}<br>${p.variants.map(v=>`${esc(v.colour)}${v.size?' / '+esc(v.size):''}: ${v.available} available (${v.stock} physical)`).join('<br>')}</p></div><div><button class="secondary small" data-edit="${esc(p.id)}">Edit</button> <button class="danger small" data-delete="${esc(p.id)}">Delete</button></div></div>`).join('')}`;$('#new-product').onclick=()=>editProduct();$$('[data-edit]').forEach(b=>b.onclick=()=>editProduct(adminData.products.find(p=>p.id===b.dataset.edit)));$$('[data-delete]').forEach(b=>b.onclick=()=>{const p=adminData.products.find(p=>p.id===b.dataset.delete);const close=modal(`<h2 id="modal-title">Delete ${esc(p.name)}?</h2><p>This removes the product from the shop. Existing orders and stock history are retained.</p><button data-close class="secondary">Keep product</button> <button id="confirm-delete" class="danger">Delete product</button>`);$('#confirm-delete').onclick=async()=>{try{await api('/api/admin/delete-product',{id:p.id});close();shop=await api('/api/shop');await admin();toast('Product removed');}catch(e){toast(e.message);}};});}
function adminImages(){let gallery=[...(adminData.settings.displayGallery||[])],busy=0;$('#admin-content').innerHTML=`<div class="section-head"><div><h2>Storefront image rail</h2><p class="muted">These images scroll across the homepage. Add up to eight JPEG, PNG, or WebP images.</p></div><label class="button secondary small">Add images<input id="rail-upload" type="file" accept="image/jpeg,image/png,image/webp" multiple hidden></label></div><div id="rail-gallery" class="rail-gallery-editor"></div><p id="rail-status" class="muted" role="status">${gallery.length} of 8 images</p>${errorField}<button id="save-rail">Save image rail</button>`;const draw=()=>{$('#rail-gallery').innerHTML=gallery.map((src,index)=>`<figure><img src="${esc(src)}" alt="Storefront rail image ${index+1}"><figcaption>Image ${index+1}<button type="button" class="danger small" data-remove-rail="${index}" aria-label="Remove image ${index+1}">Remove</button></figcaption></figure>`).join('')||'<div class="empty">No scrolling images selected.</div>';$$('[data-remove-rail]').forEach(button=>button.onclick=()=>{gallery.splice(Number(button.dataset.removeRail),1);draw();$('#rail-status').textContent=`${gallery.length} of 8 images · Unsaved changes`;});};draw();$('#rail-upload').onchange=async event=>{const files=[...event.target.files];if(files.length+gallery.length>8){toast('Use up to eight images');event.target.value='';return;}busy++;try{for(const file of files){$('#rail-status').textContent='Uploading '+file.name;const response=await fetch('/api/admin/upload',{method:'POST',headers:{'X-CSRF-Token':csrf},body:file});const result=await response.json();if(!response.ok)throw Error(result.error);gallery.push(result.url);draw();}$('#rail-status').textContent=`${gallery.length} of 8 images · Unsaved changes`;}catch(error){toast(error.message);}finally{busy--;event.target.value='';}};$('#save-rail').onclick=async()=>{if(busy){toast('Wait for uploads to finish');return;}const settings=adminData.settings;try{await api('/api/admin/settings',{...settings,displayGallery:gallery,lowStock:Number(settings.lowStock),emailEnabled:!!settings.emailEnabled,deliveryAreas:settings.deliveryAreas||[]});shop=await api('/api/shop');await admin();toast('Storefront images saved');}catch(error){$('#admin-content .form-error').textContent=error.message;}};}
function modal(content){const el=document.createElement('div');el.className='modal';el.innerHTML=`<div class="modal-panel" role="dialog" aria-modal="true" aria-labelledby="modal-title">${content}</div>`;document.body.append(el);const previous=document.activeElement;function close(){el.remove();document.removeEventListener('keydown',keys);previous?.focus();}function keys(e){if(e.key==='Escape')close();if(e.key==='Tab'){const f=[...el.querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled&&!x.hidden);if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus();}}}document.addEventListener('keydown',keys);el.querySelector('[data-close]').onclick=close;el.querySelector('input,button')?.focus();return close;}
function editProduct(p={name:'',description:'',category:'Bags',photo:'',visible:true,variants:[{colour:'',size:'',price:0,cost:0,stock:0}]}){
let photo=p.photo,galleryBusy=false,galleryPhotos=(p.photos||[]).filter(x=>x&&x!==p.photo);
const close=modal(`<div class="modal-head"><h2 id="modal-title">${p.id?'Edit':'Add'} product</h2><button class="secondary" data-close aria-label="Close">×</button></div><form id="product-form" class="form"><label>Product name<input name="name" value="${esc(p.name)}" maxlength="120" required></label><label>Description<textarea name="description" maxlength="3000" required>${esc(p.description)}</textarea></label><label>Material / details (optional)<input name="material" value="${esc(p.material||'')}" maxlength="300"></label><label>Care instructions (optional)<textarea name="care" maxlength="2000">${esc(p.care||'')}</textarea></label><label>Category<select id="product-category" name="category"><option ${p.category==='Bags'?'selected':''}>Bags</option><option ${p.category==='Shoes'?'selected':''}>Shoes</option></select></label><label>Product photo<input id="photo-file" type="file" accept="image/jpeg,image/png,image/webp"><small>JPEG, PNG or WebP · up to 4 MB. Metadata is stripped on upload.</small></label><p id="upload-state" class="muted">${photo?'Current image saved':'No image uploaded'}</p><button type="button" id="remove-photo" class="secondary small" ${photo?'':'hidden'}>Remove main photo</button><label>Additional product photos<input id="gallery-files" type="file" multiple accept="image/jpeg,image/png,image/webp"><small>Up to eight gallery images, 4 MB each.</small></label><div id="gallery-editor" class="gallery-editor"></div><p id="gallery-upload-state" class="gallery-upload-state" role="status"></p><label class="check"><input name="visible" type="checkbox" ${p.visible?'checked':''}>Visible in the shop</label><h3>Variants</h3><p class="muted">Prices and supplier costs below are in naira. Existing variants are retained for order history.</p><div id="variants"></div><button type="button" id="add-variant" class="secondary">Add another option +</button>${errorField}<button type="submit">Save product</button></form>`);const drawGallery=()=>{$('#gallery-editor').innerHTML=galleryPhotos.map((src,i)=>`<div><img src="${esc(src)}" alt="Gallery image ${i+1}"><button type="button" class="secondary" data-remove-photo="${i}">Remove</button></div>`).join('');$$('[data-remove-photo]').forEach(b=>b.onclick=()=>{galleryPhotos.splice(Number(b.dataset.removePhoto),1);drawGallery();});};drawGallery();$('#gallery-files').onchange=async e=>{const files=[...e.target.files];if(files.length+galleryPhotos.length+(photo?1:0)>8){toast('Use up to eight photos in total');return;}galleryBusy=true;try{for(const file of files){$('#gallery-upload-state').textContent='Uploading '+file.name;const r=await fetch('/api/admin/upload',{method:'POST',headers:{'X-CSRF-Token':csrf},body:file});const d=await r.json();if(!r.ok)throw Error(d.error);galleryPhotos.push(d.url);drawGallery();}$('#gallery-upload-state').textContent='Gallery images uploaded. Save the product to apply.';}catch(e){toast(e.message);}finally{galleryBusy=false;}};const variants=p.variants.map(v=>({...v,size:p.category==='Bags'?'One size':v.size}));
const draw=()=>{$('#variants').innerHTML=variants.map((v,i)=>`<fieldset class="variant-editor" data-variant-index="${i}"><legend>Option ${i+1}</legend><label>Colour<input data-v="colour" value="${esc(v.colour)}" required maxlength="80"></label>${$('#product-category').value==='Bags'?'':'<label>Size<input data-v="size" value="'+esc(v.size)+'" required maxlength="80"></label>'}<label>Price (₦)<input data-v="price" type="number" min="1" step="0.01" value="${v.price/100}" required></label><label>Supplier cost (₦)<input data-v="cost" type="number" min="0" step="0.01" value="${v.cost/100}" required></label><label>Physical quantity<input data-v="stock" type="number" min="0" step="1" value="${v.stock}" required></label></fieldset>`).join('');};
const collect=()=>$$('[data-variant-index]').forEach(el=>{const v=variants[Number(el.dataset.variantIndex)];el.querySelectorAll('[data-v]').forEach(input=>{const k=input.dataset.v;v[k]=['price','cost'].includes(k)?Math.round(Number(input.value)*100):k==='stock'?Number(input.value):input.value;});if($('#product-category').value==='Bags')v.size='One size';});
draw();$('#product-category').onchange=()=>{collect();variants.forEach(v=>{if($('#product-category').value==='Bags')v.size='One size';else if(v.size==='One size')v.size='';});draw();};$('#add-variant').onclick=()=>{collect();variants.push({colour:'',size:$('#product-category').value==='Bags'?'One size':'',price:0,cost:0,stock:0});draw();};
let uploading=false;$('#photo-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;uploading=true;try{const r=await fetch('/api/admin/upload',{method:'POST',headers:{'X-CSRF-Token':csrf},body:file});const d=await r.json();if(!r.ok)throw Error(d.error);photo=d.url;$('#upload-state').textContent='Photo uploaded and validated.';$('#remove-photo').hidden=false;
} catch (e) { toast(e.message); } finally { uploading = false; }}
bindForm('#product-form',async d=>{if(uploading||galleryBusy)throw Error('Wait for the photo upload to finish');collect();await api('/api/admin/product',{id:p.id,name:d.name,description:d.description,category:d.category,visible:d.visible==='on',photo,variants,photos:galleryPhotos,material:d.material,care:d.care});close();await admin();toast('Product saved');});}
function adminCustom(){$('#admin-content').innerHTML=`<div class="narrow"><h2>A personal find.</h2><p class="muted">Create a custom order after discussing the request on WhatsApp. Only take payment once the item is physically available. Payment links expire in 30 minutes.</p><form id="custom-form" class="form panel">${customerFields()}<label>Agreed item description<textarea name="description" required maxlength="500"></textarea></label><div class="form-row"><label>Colour<input name="colour" required maxlength="80"></label><label>Size<input name="size" required maxlength="80"></label></div><div class="form-row"><label>Unit price (₦)<input name="price" type="number" min="1" step="0.01" required></label><label>Unit supplier cost (₦)<input name="cost" type="number" min="0" step="0.01" required></label></div><label>Quantity<input name="quantity" type="number" min="1" max="100" value="1" required></label>${deliveryFields()}<label class="check"><input name="available" type="checkbox" required>I confirm this custom stock is physically available and set aside, separate from catalogue stock.</label>${errorField}<button type="submit">Create secure payment link</button><div id="custom-result"></div></form></div>`;wireDelivery();let key=crypto.randomUUID();bindForm('#custom-form',async d=>{const r=await api('/api/admin/custom',{...d,price:Math.round(Number(d.price)*100),cost:Math.round(Number(d.cost)*100),quantity:Number(d.quantity),physicallyAvailable:d.available==='on',idempotency:key});$('#custom-result').innerHTML=`<div class="notice success"><strong>${esc(r.number)}</strong><p>Expires: ${new Date(r.expires).toLocaleString('en-NG',{timeZone:'Africa/Lagos',timeZoneName:'short'})}</p><label>Private payment link<input readonly value="${esc(r.url)}"></label><a class="link" href="${esc(r.url)}" target="_blank" rel="noopener">Review order ↗</a></div>`;});}
function adminMoney(){const r=adminData.report;$('#admin-content').innerHTML=`<div class="two-col"><section><h2>Money, made clear.</h2><div class="panel">${[['Gross verified payments',r.gross],['Confirmed refunds',r.refunds],['Net revenue',r.revenue],['Allocated supplier costs',r.cost],['Recorded expenses',r.expenses],['Estimated profit',r.estimatedProfit]].map(([n,v])=>`<div class="summary-row"><span>${n}</span><strong>${cash(v)}</strong></div>`).join('')}</div><p class="notice">Net revenue = verified payments (including delivery fees) minus confirmed refunds. Estimated profit = net revenue minus supplier costs captured at checkout and recorded expenses. Restocked cancelled items reverse their supplier cost. Enter delivery costs, payment fees and other expenses; unrecorded costs and tax are not included. Test payments are included while testing.</p></section><section><h3>Record an expense</h3><form id="expense-form" class="form"><label>Description<input name="description" required maxlength="300"></label><label>Amount (₦)<input name="amount" type="number" step="0.01" min="0.01" required></label>${errorField}<button type="submit">Save expense</button></form><div class="spaced">${adminData.expenses.map(e=>`<div class="summary-row"><span>${esc(e.description)}</span><strong>${cash(e.amount)}</strong></div>`).join('')}</div></section></div>`;bindForm('#expense-form',async d=>mutate('/api/admin/expense',{description:d.description,amount:Math.round(Number(d.amount)*100)}));}
function adminNotifications(){$('#admin-content').innerHTML=`<div class="section-head"><h2>Your inbox</h2><button class="secondary small" id="refresh-notices">Refresh</button></div><div class="panel"><h3>Optional owner push notifications</h3><p class="push-help">Enable push in Settings, then use this button on each device. Your browser will ask permission. HTTPS is required outside localhost. On supported iPhones/iPads, add this site to the Home Screen first and open it from there. Notifications show only “Store update” and never customer details. Email and the dashboard still work if push is unavailable.</p><button id="enable-push" class="secondary">Enable on this device</button></div><div class="spaced">${adminData.notifications.map(n=>`<article class="notification ${!n.read&&n.channel==='dashboard'?'unread':''}"><div class="order-head"><h3>${esc(n.subject)}</h3><span class="pill">${esc(n.channel)} / ${esc(n.status)}</span></div><p class="muted">Attempts: ${n.attempts}${n.error?' · '+esc(n.error):''}</p>${n.channel==='email'?`<details><summary>Message / development outbox</summary><pre>${esc(n.body)}</pre></details>`:''}<div class="actions">${!n.read?`<button class="secondary small" data-notification="${n.id}" data-action="read">Mark read</button>`:''}${['failed','development'].includes(n.status)?`<button class="secondary small" data-notification="${n.id}" data-action="retry">Retry delivery</button>`:''}</div></article>`).join('')||'<div class="empty">No notifications yet.</div>'}</div>`;$('#refresh-notices').onclick=admin;$$('[data-notification]').forEach(b=>b.onclick=async()=>{try{await mutate('/api/admin/notification',{id:b.dataset.notification,action:b.dataset.action});}catch(e){toast(e.message);}});$('#enable-push').onclick=async()=>{try{if(!adminData.settings.pushEnabled)throw Error('Enable owner push in Settings first.');if(!adminData.pushKey)throw Error('VAPID keys need to be configured on the server first.');if(!('serviceWorker'in navigator)||!('PushManager'in window))throw Error('This browser does not support Web Push.');if(await Notification.requestPermission()!=='granted')throw Error('Notification permission was not granted. You can change it in browser settings.');const reg=await navigator.serviceWorker.register('/sw.js');await navigator.serviceWorker.ready;const k=adminData.pushKey.replace(/-/g,'+').replace(/_/g,'/');const key=Uint8Array.from(atob(k+'='.repeat((4-k.length%4)%4)),c=>c.charCodeAt(0));const sub=await reg.pushManager.getSubscription()||await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});await api('/api/admin/push',{subscription:sub.toJSON()});toast('This device is subscribed');}catch(e){toast(e.message);}};}
function adminSettings(){const s=adminData.settings;$('#admin-content').innerHTML=`<div class="narrow"><h2>Make it your own.</h2><form id="settings-form" class="form"><label>Store name<input name="brand" value="${esc(s.brand)}" required maxlength="80"></label><label>Logo image path<input name="logo" value="${esc(s.logo||'')}" readonly></label><label>Replace logo<input id="brand-file" type="file" accept="image/jpeg,image/png,image/webp"></label><label>Tagline<input name="tagline" value="${esc(s.tagline)}" required maxlength="180"></label><label>Owner notification email<input name="ownerEmail" type="email" value="${esc(s.ownerEmail)}"></label><label>Business WhatsApp number<input name="whatsapp" value="${esc(s.whatsapp)}" placeholder="234 followed by 10 digits" pattern="234[789][0-9]{9}"><small>No number is invented or provided by default.</small></label><label>ACU pickup instructions<textarea name="pickupInstructions" required maxlength="1000">${esc(s.pickupInstructions)}</textarea></label><label>Pickup timeframe<input name="pickupTime" value="${esc(s.pickupTime)}" required maxlength="160"></label><h3>Homepage display pictures</h3><p>Upload your Coach bag and slip-on photos here as style inspiration. These do not create purchasable products.</p>${[['bagDisplay','Bag display photo'],['shoeDisplay','Slip-on display photo']].map(([key,label])=>`<label>${label}<input type="hidden" name="${key}" value="${esc(s[key]||'')}"><input type="file" accept="image/jpeg,image/png,image/webp" data-display-upload="${key}"><small data-display-status="${key}">${s[key]?'Photo saved':''}</small></label>`).join('')}<label>Low-stock threshold<input name="lowStock" type="number" min="0" max="100" value="${s.lowStock}" required></label><label class="check"><input name="emailEnabled" type="checkbox" ${s.emailEnabled?'checked':''}>Email order confirmations and updates</label><label class="check"><input name="pushEnabled" type="checkbox" ${s.pushEnabled?'checked':''}>Enable optional owner Web Push</label><h3>Local delivery areas</h3><p class="muted">Add only areas you actually serve. Fees below are in naira.</p><div id="areas"></div><button type="button" id="add-area" class="secondary">Add delivery area +</button>${errorField}<button type="submit">Save settings</button></form></div>`;$('#brand-file').onchange=async e=>{try{const r=await fetch('/api/admin/upload',{method:'POST',headers:{'X-CSRF-Token':csrf},body:e.target.files[0]});const d=await r.json();if(!r.ok)throw Error(d.error);$('[name=logo]').value=d.url;toast('Logo uploaded; save settings to apply');}catch(e){toast(e.message);}};let displayUploading=0;$$('[data-display-upload]').forEach(input=>input.onchange=async()=>{const file=input.files[0];if(!file)return;displayUploading++;try{const r=await fetch('/api/admin/upload',{method:'POST',headers:{'X-CSRF-Token':csrf},body:file});const d=await r.json();if(!r.ok)throw Error(d.error);$('[name='+input.dataset.displayUpload+']').value=d.url;$('[data-display-status='+input.dataset.displayUpload+']').textContent='Uploaded. Save settings to publish.';}catch(e){toast(e.message);}finally{displayUploading--;}});let areas=s.deliveryAreas.map(a=>({...a}));const collect=()=>$$('[data-area]').forEach(el=>{const a=areas[Number(el.dataset.area)];el.querySelectorAll('[data-a]').forEach(input=>a[input.dataset.a]=input.dataset.a==='fee'?Math.round(Number(input.value)*100):input.value);});const draw=()=>{$('#areas').innerHTML=areas.map((a,i)=>`<fieldset class="form spaced" data-area="${i}"><legend>Delivery area ${i+1}</legend><label>Area name<input data-a="name" value="${esc(a.name)}" maxlength="120" required></label><div class="form-row"><label>Fee (₦)<input data-a="fee" type="number" value="${a.fee/100}" min="0" step="0.01" required></label><label>Estimated timeframe<input data-a="timeframe" value="${esc(a.timeframe)}" maxlength="160" required></label></div><button class="danger small" type="button" data-remove-area="${i}">Remove area</button></fieldset>`).join('');$$('[data-remove-area]').forEach(b=>b.onclick=()=>{collect();areas.splice(Number(b.dataset.removeArea),1);draw();});};draw();$('#add-area').onclick=()=>{collect();areas.push({id:crypto.randomUUID(),name:'',fee:0,timeframe:''});draw();};bindForm('#settings-form',async d=>{if(displayUploading)throw Error('Wait for your photos to finish uploading');collect();await api('/api/admin/settings',{...d,lowStock:Number(d.lowStock),emailEnabled:d.emailEnabled==='on',pushEnabled:d.pushEnabled==='on',deliveryAreas:areas});shop=await api('/api/shop');await admin();toast('Settings saved');});}
async function start(){try{shop=await api('/api/shop');document.title=shop.settings.brand+' · Bags & shoes';const path=decodeURIComponent(location.pathname);if(path==='/')catalogue(true);else if(path==='/shop')catalogue();else if(path.startsWith('/product/'))product(path.slice(9));else if(path==='/cart')cartPage();else if(path==='/checkout')checkout();else if(path==='/request')requestPage();else if(path==='/saved')showWishlist(context());else if(path==='/help')showHelp(context());else if(path==='/track')showTrack(context());else if(path.startsWith('/order/'))await orderPage(path.slice(7));else if(path.startsWith('/dev-pay/'))await orderPage(path.slice(9),true);else if(path==='/admin/setup')await ownerSetup();else if(path==='/admin')await admin();else shell('<div class="page empty"><h1>Page not found</h1><a class="button" href="/">Back to the shop</a></div>');enhanceStore(context());}catch(e){shell(`<div class="page narrow"><h1 class="page-title">We couldn't open this page.</h1><p>${esc(e.message)}</p><p class="muted">Open the shop through the running Node server, not by opening index.html directly.</p><button id="retry">Try again</button> <a class="button secondary" href="/">Back to shop</a></div>`);$('#retry').onclick=()=>location.reload();}}
function context(){return {$,$$,shop,adminData,adminTab,api,esc,cash,toast,shell,cards,bindForm,modal,admin,currentTab:()=>adminTab,setTab:t=>{adminTab=t;renderAdmin();}};}
start();
